function compute(p) {
  var Q = p.Q, K = p.K, V = p.V;
  var n = Q.length, m = K.length;
  var dk = (n > 0 && Q[0]) ? Q[0].length : 0;
  var dv = (m > 0 && V[0]) ? V[0].length : 0;
  var scale = p.scaled ? Math.sqrt(dk) : 1;
  var S = [], Z = [], A = [], O = [];
  var i, j, t, s, mx, ex, sum;
  for (i = 0; i < n; i++) {
    S.push([]); Z.push([]); A.push([]); O.push([]);
    for (j = 0; j < m; j++) {
      s = 0;
      for (t = 0; t < dk; t++) s += Q[i][t] * K[j][t];
      S[i].push(s);
      Z[i].push(s / scale);
    }
    mx = -Infinity;
    for (j = 0; j < m; j++) if (Z[i][j] > mx) mx = Z[i][j];
    sum = 0;
    for (j = 0; j < m; j++) { ex = Math.exp(Z[i][j] - mx); A[i].push(ex); sum += ex; }
    for (j = 0; j < m; j++) A[i][j] = A[i][j] / sum;
    for (t = 0; t < dv; t++) {
      s = 0;
      for (j = 0; j < m; j++) s += A[i][j] * V[j][t];
      O[i].push(s);
    }
  }
  var rowSums = [], maxW = [], entropy = [];
  for (i = 0; i < n; i++) {
    s = 0;
    for (j = 0; j < m; j++) s += A[i][j];
    rowSums.push(s);
    mx = -Infinity;
    for (j = 0; j < m; j++) if (A[i][j] > mx) mx = A[i][j];
    maxW.push(mx);
    var h = 0;
    for (j = 0; j < m; j++) if (A[i][j] > 0) h -= A[i][j] * Math.log(A[i][j]);
    entropy.push(h);
  }
  var flat = [];
  for (i = 0; i < n; i++) for (j = 0; j < m; j++) flat.push(Z[i][j]);
  var zmin = Math.min.apply(null, flat), zmax = Math.max.apply(null, flat);
  var warning = null;
  if (dk === 0 || m === 0) warning = 'Add at least one key/value row and one dimension to see attention.';
  else if (!p.scaled && dk >= 8) warning = 'Scaling is off and d_k is large: scores are spread out, so softmax is nearly one-hot and gradients shrink.';
  return {
    scores: S, scaledScores: Z, weights: A, output: O,
    rowSums: rowSums, maxWeight: maxW, entropy: entropy,
    dk: dk, dv: dv, n: n, m: m, scale: scale,
    scoreMin: zmin, scoreMax: zmax,
    qLabels: Q.map(function (_, k) { return 'q' + (k + 1); }),
    kLabels: K.map(function (_, k) { return 'k' + (k + 1); }),
    vLabels: V.map(function (_, k) { return 'v' + (k + 1); }),
    oLabels: O.map(function (_, k) { return 'o' + (k + 1); }),
    warning: warning
  };
}
